-- Crear la base de datos
CREATE DATABASE logistics;
GO

-- Usar la base de datos
USE logistics;
GO

-- Crear tabla de nodos
CREATE TABLE nodes (
    id INT NOT NULL PRIMARY KEY,
    city_name VARCHAR(50) NOT NULL,
    state VARCHAR(100) NOT NULL,
    latitude FLOAT NOT NULL,       -- DOUBLE en MySQL → FLOAT en SQL Server
    longitude FLOAT NOT NULL,
    listed BIT DEFAULT 0           -- BOOLEAN en MySQL → BIT en SQL Server
);
GO

-- Crear tabla de aristas
CREATE TABLE edges (
    origin_node INT NOT NULL,
    destination_node INT NOT NULL,
    range_km FLOAT NOT NULL,
    locked_road BIT DEFAULT 0,     -- BOOLEAN → BIT
    gas_cost FLOAT NOT NULL,
    cash_cost FLOAT NOT NULL,
    time_lapse TIME NOT NULL,
    google_json NVARCHAR(MAX) NOT NULL, -- JSON en MySQL → NVARCHAR(MAX) en SQL Server
    CONSTRAINT PK_edges PRIMARY KEY (origin_node, destination_node)
);
GO


